methods.text:
search(): void {
    this.activeSearch.set(this.filterForm.controls.search.value.trim());
    this.pageNo.set(1);
    this.requestList();
  }

onLazyLoad(event: TableLazyLoadEvent): void {
    const paging = resolveListPaging(event, { pageNo: this.pageNo(), pageSize: this.pageSize() });
    if (!paging.changed) return;
    this.pageNo.set(paging.pageNo);
    this.pageSize.set(paging.pageSize);
    this.requestList();
  }

resetFilters(): void {
    this.filterForm.reset();
    this.search();
  }

private requestList(): void {
    this.listRequests.next({
      pageNo: this.pageNo(),
      pageSize: this.pageSize(),
      search: this.activeSearch(),
    });
  }

search(force = true, resetPage = true): void {
    const raw = this.filterForm.getRawValue();
    if (this.filterForm.invalid) { this.filterForm.markAllAsTouched(); return; }
    const [dateFrom, dateTo] = parseDateRange(raw.dateRange);
    if (raw.dateRange && (!dateFrom || (dateTo && dateTo < dateFrom))) {
      this.errorMessage.set('validationMessages.date'); return;
    }
    this.activeFilters = {
      no: raw.no.trim(),
      customerId: raw.customerId,
      approvalStatus: raw.approvalStatus,
      dateFrom: dateFrom ?? undefined,
      dateTo: dateTo ?? undefined,
      plateNoOrChassisNo: raw.plateNoOrChassisNo.trim(),
      status: raw.status,
      jobType: raw.jobType,
      branchId: raw.branchId,
      createdBy: raw.createdBy ?? undefined,
      insuranceCompany: raw.insuranceCompany ?? undefined,
    };
    if (resetPage) this.pageNo.set(1);
    this.requestList({
      pageNo: this.pageNo(),
      pageSize: this.pageSize(),
      filters: this.activeFilters,
      sortField: this.sortField(),
      sortOrder: this.sortOrder(),
    }, force);
  }

onLazyLoad(event: TableLazyLoadEvent): void {
    const rawField = typeof event.sortField === 'string'
      ? event.sortField
      : (Array.isArray(event.sortField) ? event.sortField[0] : undefined);
    const allowedSort = new Set(this.columns.filter((column) => column.sortable).map((column) => column.field));
    const sortField = rawField && allowedSort.has(rawField as keyof JobEstimationListRow) ? rawField : this.sortField();
    const sortOrder = event.sortOrder === 1 || event.sortOrder === -1 ? event.sortOrder : this.sortOrder();
    const { pageNo, pageSize } = resolveListPaging(event, { pageNo: this.pageNo(), pageSize: this.pageSize() });
    this.pageNo.set(pageNo);
    this.pageSize.set(pageSize);
    this.sortField.set(sortField);
    this.sortOrder.set(sortOrder);
    this.requestList({ pageNo, pageSize, filters: this.activeFilters, sortField, sortOrder });
  }

private requestList(query: JobEstimationListQuery, force = false): void {
    const key = JSON.stringify(query);
    if (!force && key === this.lastQueryKey) return;
    this.lastQueryKey = key;
    writeListRoute(this.router, this.route, this.editorReturnQueryParams());
    this.listQuery$.next(query);
  }

resetFilters(): void {
    this.filterForm.reset({ no: '', customerId: null, approvalStatus: null, dateRange: currentMonthRange(),
      plateNoOrChassisNo: '', status: null, jobType: null, branchId: null, createdBy: null, insuranceCompany: null });
    this.search();
  }

private toQueryParams(filters: JobEstimationFilters): Record<string, string | number> {
    const params: Record<string, string | number> = {};
    Object.entries(filters).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') params[key] = value;
    });
    return params;
  }

private editorReturnQueryParams(): Record<string, string | number> {
    return {
      ...this.toQueryParams(this.activeFilters),
      returnPageNo: this.pageNo(),
      returnPageSize: this.pageSize(),
      returnSortField: this.sortField(),
      returnSortOrder: this.sortOrder(),
      ...(this.activeFilters.dateFrom || this.activeFilters.dateTo ? {} : { returnDateRangeEmpty: 1 }),
    };
  }

private restoreStateFromRoute(): void {
    const params = this.route.snapshot.queryParamMap;
    const state = readListRoute(this.route);
    const numberParam = (name: string): number | null => state.number(name);
    const dateParam = (name: string): Date | null => {
      const value = parseDateValue(state.text(name));
      return value ? toPickerDate(value) : null;
    };
    const dateFrom = dateParam('dateFrom');
    const dateTo = dateParam('dateTo');
    const dateRange = params.get('returnDateRangeEmpty') === '1'
      ? null
      : dateFrom && dateTo
        ? [dateFrom, dateTo]
        : dateFrom ? [dateFrom]
          : dateTo ? [dateTo]
            : currentMonthRange();

    this.filterForm.patchValue({
      no: params.get('no') ?? '',
      customerId: numberParam('customerId'),
      approvalStatus: numberParam('approvalStatus') as JobEstimationApprovalStatus | null,
      dateRange,
      plateNoOrChassisNo: params.get('plateNoOrChassisNo') ?? '',
      status: numberParam('status') as JobEstimationStatus | null,
      jobType: numberParam('jobType') as JobEstimationType | null,
      branchId: this.currentBranch.filterBranchId(this.route.snapshot.queryParamMap),
      createdBy: params.get('createdBy') || null,
      insuranceCompany: params.get('insuranceCompany') || null,
    }, { emitEvent: false });

    const requestedPage = numberParam('returnPageNo');
    const requestedSize = numberParam('returnPageSize');
    const requestedSort = params.get('returnSortField');
    const requestedOrder = numberParam('returnSortOrder');
    const allowedSort = new Set(this.columns.filter((column) => column.sortable).map((column) => column.field));
    if (requestedPage && requestedPage > 0) this.pageNo.set(Math.floor(requestedPage));
    if (requestedSize && this.rowsPerPageOptions.includes(requestedSize)) this.pageSize.set(requestedSize);
    if (requestedSort && allowedSort.has(requestedSort as keyof JobEstimationListRow)) this.sortField.set(requestedSort);
    if (requestedOrder === 1 || requestedOrder === -1) this.sortOrder.set(requestedOrder);
  }

