methods.text:
search(force = true, resetPage = true): void {
    if (this.actionBusy()) return;
    if (this.filterForm.invalid) { this.filterForm.markAllAsTouched(); return; }
    const raw = this.filterForm.getRawValue();
    const [from, to] = parseDateRange(raw.dateRange);
    if (raw.dateRange && ((!from || !to) || from > to)) {
      this.errorMessage.set('validationMessages.date');
      return;
    }
    this.activeFilters = {
      recordType: raw.recordType ?? null,
      no: raw.no.trim(),
      estimationNo: raw.estimationNo.trim(),
      workOrderNo: raw.workOrderNo.trim(),
      status: raw.status,
      hasInvoice: raw.hasInvoice,
      customerId: raw.customerId,
      dateFrom: from ?? undefined,
      dateTo: to ?? undefined,
      plateNoOrChassisNo: raw.plateNoOrChassisNo.trim(),
      jobType: raw.jobType,
      branchId: raw.branchId,
      ownership: raw.ownership,
      createdBy: raw.createdBy ?? '',
      insuranceCompany: raw.insuranceCompany ?? '',
      salesPersonId: raw.salesPersonId,
      labourType: raw.labourType,
      itemType: raw.itemType,
    };
    if (resetPage) this.pageNo.set(1);
    this.writeStateToRoute();
    this.requestList({
      pageNo: this.pageNo(), pageSize: this.pageSize(), filters: this.activeFilters,
      sortField: this.sortField(), sortOrder: this.sortOrder(),
    }, force);
  }

resetFilters(): void {
    if (this.actionBusy()) return;
    this.filterForm.reset({
      recordType: null,
      no: '',
      estimationNo: '',
      workOrderNo: '',
      status: JobStatus.Open,
      hasInvoice: null,
      customerId: null,
      dateRange: currentMonthRange(),
      plateNoOrChassisNo: '',
      jobType: null,
      branchId: null,
      ownership: null,
      createdBy: null,
      insuranceCompany: null,
      salesPersonId: null,
      labourType: null,
      itemType: null,
    });
    this.search(true, true);
  }

onLazyLoad(event: TableLazyLoadEvent): void {
    if (this.actionBusy()) return;
    const rawSort = typeof event.sortField === 'string' ? event.sortField : undefined;
    // Sortable fields come from the columns (UI block 5) — one list, backend-confirmed.
    const sortable = new Set(this.columns.filter((column) => column.sortable).map((column) => String(column.field)));
    const sortField = rawSort && sortable.has(rawSort) ? rawSort : this.sortField();
    const sortOrder = event.sortOrder === 1 || event.sortOrder === -1 ? event.sortOrder : this.sortOrder();
    const { pageNo, pageSize } = resolveListPaging(event, {
      pageNo: this.pageNo(),
      pageSize: this.pageSize(),
    });
    this.pageNo.set(pageNo);
    this.pageSize.set(pageSize);
    this.sortField.set(sortField);
    this.sortOrder.set(sortOrder);
    this.writeStateToRoute();
    this.requestList({ pageNo, pageSize, filters: this.activeFilters, sortField, sortOrder });
  }

private requestList(query: JobListQuery, force = false): void {
    const key = JSON.stringify(query);
    if (!force && key === this.lastQueryKey) return;
    this.lastQueryKey = key;
    this.listQuery$.next(query);
  }

private restoreStateFromRoute(): void {
    const state = readListRoute(this.route);
    const number = state.number;
    const text = state.text;
    const dateFrom = parseDateValue(text('dateFrom'));
    const dateTo = parseDateValue(text('dateTo'));
    this.filterForm.patchValue({
      recordType: number('recordType') as JobRecordType | null,
      no: text('no'), estimationNo: text('estimationNo'), workOrderNo: text('workOrderNo'),
      // No status parameter means the default Open; "all" means the user cleared it.
      status: text('status') === 'all' ? null : (number('status') as JobStatus | null) ?? JobStatus.Open,
      hasInvoice: text('hasInvoice') === 'true' ? true : text('hasInvoice') === 'false' ? false : null,
      customerId: number('customerId'),
      dateRange: dateFrom || dateTo ? [dateFrom ? toPickerDate(dateFrom) : null, dateTo ? toPickerDate(dateTo) : null] as Date[] : (state.text('dateRange') === 'all' ? null : currentMonthRange()),
      plateNoOrChassisNo: text('plateNoOrChassisNo'),
      jobType: number('jobType') as JobType | null,
      branchId: this.currentBranch.filterBranchId(this.route.snapshot.queryParamMap), ownership: number('ownership') as JobOwnership | null,
      createdBy: text('createdBy') || null, insuranceCompany: text('insuranceCompany') || null,
      salesPersonId: number('salesPersonId'), labourType: number('labourType') as JobLabourType | null,
      itemType: number('itemType') as JobItemType | null,
    }, { emitEvent: false });
    this.pageNo.set(Math.max(1, number('pageNo') ?? 1));
    this.pageSize.set(Math.max(10, number('pageSize') ?? DEFAULT_PAGE_SIZE));
    const sortField = text('sortField');
    if (sortField) this.sortField.set(sortField);
    const sortOrder = number('sortOrder');
    if (sortOrder === 1 || sortOrder === -1) this.sortOrder.set(sortOrder);
  }

private writeStateToRoute(): void {
    const params: Record<string, string | number | null> = {
      ...this.returnQueryParams(),
      pageNo: this.pageNo(),
      pageSize: this.pageSize(),
      sortField: this.sortField(),
      sortOrder: this.sortOrder(),
    };
    writeListRoute(this.router, this.route, params);
  }

