onPagination(event: DataTablePaginationEvent): void {
        const paging = resolveListPaging({ first: event.first, rows: event.pageSize }, { pageNo: this.pageNo(), pageSize: this.pageSize() });
        if (!paging.changed)
            return;
        this.pageNo.set(paging.pageNo);
        this.pageSize.set(paging.pageSize);
        this.listQueries.next(this.appliedFilters);
    }

submitSearch(): void {
