  })

toSignal(this.form.valueChanges.pipe(
    map(() => this.form.getRawValue()), startWith(this.form.getRawValue()),
  ), { requireSync: true })

computed(() => {
    const draft = this.draft();
    const values = this.values().quantities;
    if (!draft) return { amount: 0, discount: 0, tax: 0, total: 0 };
    const decimals = draft.moneyDecimalPlaces;
    const taxable = this.rows().map((row, index) => ({
      amount: roundMoney(Math.max(0, Number(values[index]) || 0) * row.source.unitPrice, decimals),
      ratePercent: draft.taxRatePercent,
    }));
    const amount = roundMoney(taxable.reduce((sum, line) => sum + line.amount, 0), decimals);
    const allConsumed = this.rows().every((row, index) => (values[index] ?? 0) === row.source.remainingQuantity);
    const availableDiscount = Math.max(0, roundMoney(draft.discount - draft.allocatedDiscount, decimals));
    const targetDiscount = draft.totalAmount > 0
      ? roundMoney(draft.discount * ((draft.orderedAmount + amount) / draft.totalAmount), decimals) : 0;
    const discount = allConsumed ? availableDiscount
      : Math.min(availableDiscount, Math.max(0, roundMoney(targetDiscount - draft.allocatedDiscount, decimals)));
    const tax = documentTax(taxable, decimals);
    return { amount, discount, tax, total: roundMoney(amount + tax - discount, decimals) };
  })

computed<ReadonlyArray<SummaryCard>>(() => {
    const totals = this.totals();
