      { id: 'tax', labelKey: 'purchaseRequest.detail.tax', value: totals.tax, format: 'money', accent: 'info', icon: 'bi bi-receipt' },
      { id: 'total', labelKey: 'purchaseRequest.grossAmount', value: totals.total, format: 'money', accent: 'primary', icon: 'bi bi-wallet2' },
    ];
  })

methods.text:
loadSources(): void {
    if (this.loading() || this.sourceLoading() || this.saving() || !this.sourceSupplierId) return;
    this.sourceLoading.set(true);
    this.sourceError.set('');
