private describeFilters(filters: PurchaseOrderFilters): string {
    const pieces: string[] = [];

    const labels: Record<string, string> = {
      no: 'no', supplierQuotationNo: 'supplierQuotationNo', branchId: 'branchId', supplierId: 'supplierId',
      vehicleId: 'vehicles', jobId: 'jobId', dateFrom: 'dateFrom', dateTo: 'dateTo', chassisNo: 'chassisNo', poType: 'poType',
      approvedStatus: 'approval.status', billStatus: 'billStatus', receiptStatus: 'receiptStatus',
      notes: 'notes', discount: 'discount', supplierName: 'supplierName', search: 'search'
    };

    Object.entries(filters).forEach(([key, value]) => {
      if (value === null || value === undefined || value === '')
        return;

      let display = String(value);

      const options = key === 'supplierId' ? this.suppliers() : key === 'branchId' ? this.branches() : key === 'vehicleId' ? this.vehicles() : key === 'jobId' ? this.jobs() : null;

      if (options)
        display = String(options.find(option => Number(option.id) === value)?.value ?? value);

      if (key === 'poType')
        display = this.translate.instant(enumKey(POType, 'purchaseOrder.types', Number(value)));

      if (key === 'approvedStatus')
        display = this.translate.instant(purchaseOrderApprovalBadge(Number(value)).label);

      if (key === 'billStatus')
        display = this.translate.instant(enumKey(PurchaseOrderBillStatus, 'purchaseOrder.billStatuses', Number(value)));
      if (key === 'receiptStatus')
        display = this.translate.instant(enumKey(PurchaseOrderReceiptStatus, 'purchaseOrder.receiptStatuses', Number(value)));

      pieces.push(`${this.translate.instant('purchaseOrder.' + labels[key])}: ${display}`);
    });

    return pieces.join(' | ');
  }

