private buildSearch(pageNo: number): FleetAlertSearch {
    const value = this.filterForm.getRawValue();
    const supportsOperationalFilters = this.activeAlert() !== 'warranty';
    return {
      pageNo,
      pageSize: this.pageSize(),
      plateNo: value.plateNo?.trim() || undefined,
      carMakeId: value.carMakeId ?? undefined,
      carModelId: value.carModelId ?? undefined,
      status: supportsOperationalFilters ? value.status ?? undefined : undefined,
      branchId: supportsOperationalFilters ? value.branchId ?? undefined : undefined,
      ownership: value.ownership ?? undefined,
      sortField: this.sortField(),
      sortOrder: this.sortOrder(),
    };
  }

loadFilterOptions(): void {
    if (this.loadingLookups()) return;
    this.loadingLookups.set(true);
    this.lookupError.set('');
    this.fleetAlertsService
      .getFilterOptions()
      .pipe(takeUntilDestroyed(this.destroyRef), finalize(() => this.loadingLookups.set(false)))
      .subscribe({
        next: (result) => {
          if (!result.isSuccess || !result.entity) {
            this.lookupError.set(result.message || 'fleetAlerts.errors.options');
            return;
          }
          this.branchOptions.set(result.entity.branches ?? []);
          this.makeOptions.set(result.entity.makes ?? []);
          this.allModelOptions.set(result.entity.models ?? []);
          this.filterModels(this.filterForm.controls.carMakeId.value);
        },
        error: (error) =>
          this.lookupError.set(
            apiErrorMessage(error, 'fleetAlerts.errors.options'),
          ),
      });
  }

private filterModels(makeId: number | null): void {
    const models = makeId === null
      ? this.allModelOptions()
      : this.allModelOptions().filter((model) => model.makeId === makeId);
    this.modelOptions.set(models);

    const selectedModelId = this.filterForm.controls.carModelId.value;
    if (
      selectedModelId !== null
      && !models.some((model) => model.id === selectedModelId)
    ) this.filterForm.controls.carModelId.setValue(null);
  }

