        this.statement.set(null);
        this.statementHasSearched.set(true);
        this.statementFirst.set(0);
        this.statementErrorMessage.set('');
        this.loading.startLoading();
        return this.statementService.getStatement(filter).pipe(
          catchError((error: unknown) => {
            this.statementErrorMessage.set(apiErrorMessage(error, 'balancesSummary.statementLoadError'));
            return EMPTY;
          }),
          finalize(() => {
            this.loadingStatement.set(false);
            this.statementForm.enable({ emitEvent: false });
            this.loading.endLoading();
          }),
        );
      })),
      takeUntilDestroyed(this.destroyRef),
    ).subscribe((response) => {
      if (!this.statementDialogVisible()) return;
      if (response.isSuccess && response.entity) {
        this.statement.set(response.entity);
        this.selectedCustomerName.set(response.entity.contact?.name ?? this.selectedCustomerName());
      } else {
        this.statement.set(null);
        this.statementErrorMessage.set(response.message || 'balancesSummary.statementLoadError');
