    this.sortField.set(sortField); this.sortOrder.set(sortOrder); this.refreshAppliedList();
  }

private appliedQuery(): BranchListQuery {
    return { pageNo: this.pageNo(), pageSize: this.pageSize(), filters: { ...this.activeFilters },
      sortField: this.sortField(), sortOrder: this.sortOrder() };
  }

props.init:
this.fb.group({
    dateRange: this.fb.control<Date[] | string | null>(currentMonthRange(), [Validators.required, dateRangeValidator]),
    recordNo: this.fb.nonNullable.control(''),
