methods.text:
search(): void {
    if (this.busy()) return;
    const filters = this.readFilters();
    if (!filters) return;
    this.activeFilters = filters;
    this.appliedFilter.set(filters);
    this.pageNo.set(1);
    this.snapshotId.set(null);
    this.exportError.set('');
    this.requestList(true);
  }

reset(): void {
    if (this.busy()) return;
    this.filterForm.reset({ dateRange: currentMonthRange(), recordNo: '', recordType: '', user: null });
    this.search();
  }

onLazyLoad(event: TableLazyLoadEvent): void {
    if (!this.activeFilters || this.exporting()) return;
    const paging = resolveListPaging(event, { pageNo: this.pageNo(), pageSize: this.pageSize() });
    const pageSize = Math.min(100, paging.pageSize);
    const field = typeof event.sortField === 'string' && this.sortableFields.has(event.sortField)
      ? event.sortField : this.sortField();
    const order = event.sortOrder === 1 || event.sortOrder === -1 ? event.sortOrder : this.sortOrder();
    const sortChanged = field !== this.sortField() || order !== this.sortOrder();
    const pageNo = sortChanged ? 1 : paging.pageNo;
    if (pageNo === this.pageNo() && pageSize === this.pageSize() && !sortChanged) return;
    this.pageNo.set(pageNo);
    this.pageSize.set(pageSize);
    this.sortField.set(field);
    this.sortOrder.set(order);
    this.exportError.set('');
    this.requestList();
  }

private readFilters(): AuditTrailFilters | null {
    this.filterForm.markAllAsTouched();
    const raw = this.filterForm.getRawValue();
    const [fromDate, toDate] = parseDateRange(raw.dateRange);
    if (this.filterForm.invalid || !fromDate || !toDate || fromDate.length !== 10 || toDate.length !== 10
      || fromDate < '0001-01-01' || fromDate > toDate || toDate >= '9999-12-31') {
      this.filterError.set('auditTrail.invalidDateRange');
      focusField('auditTrailDateRange', { openOverlay: false });
      return null;
    }
    this.filterError.set('');
    return { fromDate, toDate, recordNo: raw.recordNo.trim() || null,
      recordType: raw.recordType.trim() || null, user: raw.user || null };
  }

private query(): AuditTrailQuery | null {
    return this.activeFilters ? { filters: { ...this.activeFilters },
      pageNo: this.pageNo(), pageSize: this.pageSize(), snapshotId: this.snapshotId(),
      sortField: this.sortField(), sortOrder: this.sortOrder() } : null;
  }

private requestList(force = false): void {
    const query = this.query();
    if (!query) return;
    const key = JSON.stringify(query);
    if (!force && key === this.lastQueryKey) return;
    this.lastQueryKey = key;
    this.writeRoute();
    this.queries.next(query);
  }

private restoreFilterForm(): void {
    if (this.disposed || this.busy()) return;
    this.filterForm.enable({ emitEvent: false });
    if (this.loadingUsers() || this.lookupError()) this.filterForm.controls.user.disable({ emitEvent: false });
  }

search(): void {
    if (this.loadingReport() || this.exporting() || this.accountLoading() || this.accountError()) return;
    if (this.filterForm.invalid) { this.filterForm.markAllAsTouched(); focusField('journal-range'); return; }
    const value = this.filterForm.getRawValue();
    const [fromDate, toDate] = parseDateRange(value.dateRange);
    this.appliedFilter = {
      fromDate: fromDate ?? undefined, toDate: toDate ?? undefined,
      voucherNo: value.voucherNo.trim() || undefined, type: value.type ?? undefined,
      chassisOrPlateNo: value.chassisOrPlateNo.trim() || undefined, accountId: value.accountId ?? undefined,
    };
    this.paging.update(state => ({ ...state, pageNo: 1 })); this.loadPage();
  }

reset(): void {
    if (this.exporting() || this.loadingReport()) return;
    this.filterForm.reset({ dateRange: currentMonthRange(), voucherNo: '', type: null, chassisOrPlateNo: '', accountId: null });
  }

pageChanged(event: DataTablePaginationEvent): void {
    if (!this.appliedFilter || this.loadingReport() || this.exporting()) return;
    const next = resolveListPaging({ first: event.first, rows: event.pageSize }, this.paging());
    if (!next.changed) return;
    this.paging.set({ pageNo: next.pageNo, pageSize: next.pageSize }); this.loadPage();
  }

onLazyLoad(event: TableLazyLoadEvent): void {
    const rows = Math.max(1, Number(event.rows ?? this.pageSize()));
    const first = Math.max(0, Number(event.first ?? 0));
    const candidate = Array.isArray(event.sortField)
      ? event.sortField[0]
      : event.sortField;
    const nextSortField = this.isSortField(candidate) ? candidate : this.sortField();
    const nextSortOrder = event.sortOrder === 1 || event.sortOrder === -1
      ? event.sortOrder
      : this.sortOrder();
    const nextPage = Math.floor(first / rows) + 1;

    if (
      nextPage === this.pageNo()
      && rows === this.pageSize()
      && nextSortField === this.sortField()
      && nextSortOrder === this.sortOrder()
    ) return;

    this.pageNo.set(nextPage);
    this.pageSize.set(rows);
    this.sortField.set(nextSortField);
    this.sortOrder.set(nextSortOrder);
    this.requestList();
  }

private requestList(): void {
    this.requests.next({
      pageNo: this.pageNo(),
      pageSize: this.pageSize(),
      sortField: this.sortField(),
      sortOrder: this.sortOrder(),
    });
  }

