onLazyLoad(event: TableLazyLoadEvent): void {
    if (this.busy()) return;
    const paging = resolveListPaging(event, { pageNo: this.pageNo(), pageSize: this.pageSize() });
    const rawSort = Array.isArray(event.sortField) ? event.sortField[0] : event.sortField;
    const sort = this.columns.some(column => column.sortable && column.field === rawSort) ? rawSort! : this.sortField();
    const order = event.sortOrder === 1 || event.sortOrder === -1 ? event.sortOrder : this.sortOrder();
    if (!paging.changed && sort === this.sortField() && order === this.sortOrder()) return;
    this.pageNo.set(paging.pageNo); this.pageSize.set(paging.pageSize); this.sortField.set(sort); this.sortOrder.set(order);
    this.requestList();
  }

private query(): AccountTypeListQuery {
    return { pageNo: this.pageNo(), pageSize: this.pageSize(), filters: { search: this.appliedSearch }, sortField: this.sortField(), sortOrder: this.sortOrder() };
  }

private requestList(): void {
    writeListRoute(this.router, this.activatedRoute, { search: this.appliedSearch || null, pageNo: this.pageNo(), pageSize: this.pageSize(), sortField: this.sortField(), sortOrder: this.sortOrder() });
    this.queries.next(this.query());
  }
